    s=s.replace('ALCANCE DE ESTA ETAPA:',common+'ALCANCE DE ESTA ETAPA:',1)
    marker='\n\nPrimero identifica y clasifica'
    assert marker in s
    s=s.replace(marker,'\n\nACTUALIZACIÓN ESPECÍFICA DEMO-INTERNET:\n'+details[num]+marker,1)
    s=s.replace('`resultados/ESTADO_GENERAL.md`','`auditoria_por_etapas/resultados/ESTADO_GENERAL.md`')
    if num=='11':s=s.replace('Cobro en efectivo, exactitud e integridad','Cobro efectivo, Yape, mixto e integridad',1)
    if num=='16':
        s=s.replace('Ventas, datos personales, documentos y afirmaciones de la interfaz.','Caso tributario de comprobantes, condiciones del medio de pago y afirmaciones de la interfaz; según contexto académico y aplicabilidad.')
        s=s.replace('para comprobantes, protección de datos y obligaciones pertinentes al negocio, y estándares relevantes solo si son aplicables','para el caso de comprobantes y las condiciones del medio de pago; otros estándares u obligaciones solo si una necesidad concreta del alcance los hace aplicables')
    p.write_text(s,encoding='utf-8')

